function lcs(a, b) {
  const m = a.length, n = b.length, dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0)) //@init
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1 //@match
      else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) //@differ
    }
  }
  return dp[m][n] //@done
}

